// Package pg connects to PostgreSQL and applies the schema migrations
// (decisions 0005 and 0009). It holds the connection settings, pool
// creation with a bounded wait for the database at start, and the goose
// migrations embedded in the binary. Nothing else.
//
// The queries generated by sqlc live in the subpackage pgdb. Run `make
// generate` after a change to migrations/ or queries/.
//
// PostgreSQL stores conversation and routing metadata only, never post text
// (decision 0004).
package pg

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"
)

// Variable names. They have no service part, so every service that uses
// the same database can share them, like the REDIS_ variables.
const (
	// EnvDSN is the connection string, as a URL
	// (postgres://user:password@host:port/db?sslmode=disable) or as
	// key=value pairs. It can hold a password and must never be logged.
	EnvDSN = "THREADROUTE_POSTGRES_DSN"
	// EnvMaxConns is the most connections in the pool.
	EnvMaxConns = "THREADROUTE_POSTGRES_MAX_CONNS"
	// EnvConnectWait is how long a service waits at start until the
	// database answers.
	EnvConnectWait = "THREADROUTE_POSTGRES_CONNECT_WAIT"
)

// Defaults.
const (
	// DefaultDSN has no password. Set a real DSN in the environment.
	DefaultDSN = "postgres://threadroute@localhost:5432/threadroute?sslmode=disable"
	// DefaultMaxConns is small on purpose: the first server has 4 GB of
	// RAM shared with Kafka and Redis, and each PostgreSQL connection is
	// one server process.
	DefaultMaxConns = 8
	// DefaultConnectWait covers a database container that starts at the
	// same time as the service.
	DefaultConnectWait = time.Minute
)

// Fixed pool settings.
const (
	// connectTimeout bounds one connection attempt.
	connectTimeout = 5 * time.Second
	// maxConnIdleTime closes connections that were not used for a while,
	// so a quiet service gives memory back to the database.
	maxConnIdleTime = 5 * time.Minute
	// maxConnLifetime replaces connections from time to time, so the pool
	// follows a database failover or restart.
	maxConnLifetime = time.Hour
	// healthCheckPeriod is how often idle connections are checked.
	healthCheckPeriod = 30 * time.Second
	// pingInterval is the pause between two pings while waiting at start.
	pingInterval = 500 * time.Millisecond
	// applicationName is shown in pg_stat_activity when the DSN does not
	// set one.
	applicationName = "threadroute"
)

// Config is the connection configuration.
type Config struct {
	// DSN is the connection string. It must never be logged.
	DSN string
	// MaxConns is the most connections in the pool, at least 1.
	MaxConns int32
	// ConnectWait bounds the wait for the database in Open.
	ConnectWait time.Duration
}

// DefaultConfig returns the defaults above.
func DefaultConfig() Config {
	return Config{DSN: DefaultDSN, MaxConns: DefaultMaxConns, ConnectWait: DefaultConnectWait}
}

// Validate reports every invalid field. The error never contains the DSN.
func (c Config) Validate() error {
	var errs []error
	if c.DSN == "" {
		errs = append(errs, errors.New("dsn is not set"))
	} else if _, err := pgxpool.ParseConfig(c.DSN); err != nil {
		errs = append(errs, errors.New("dsn cannot be parsed"))
	}
	if c.MaxConns < 1 {
		errs = append(errs, fmt.Errorf("max conns %d is less than 1", c.MaxConns))
	}
	if c.ConnectWait <= 0 {
		errs = append(errs, fmt.Errorf("connect wait %s is not positive", c.ConnectWait))
	}
	return errors.Join(errs...)
}

// poolConfig turns c into a pool configuration.
func (c Config) poolConfig() (*pgxpool.Config, error) {
	if err := c.Validate(); err != nil {
		return nil, err
	}
	pc, err := pgxpool.ParseConfig(c.DSN)
	if err != nil {
		// Not reached after Validate. The parse error may quote the DSN,
		// so it is not wrapped.
		return nil, errors.New("dsn cannot be parsed")
	}
	pc.MaxConns = c.MaxConns
	pc.MinConns = 0
	pc.MaxConnIdleTime = maxConnIdleTime
	pc.MaxConnLifetime = maxConnLifetime
	pc.HealthCheckPeriod = healthCheckPeriod
	pc.ConnConfig.ConnectTimeout = connectTimeout
	if _, ok := pc.ConnConfig.RuntimeParams["application_name"]; !ok {
		pc.ConnConfig.RuntimeParams["application_name"] = applicationName
	}
	return pc, nil
}

// Open creates a connection pool and waits until the database answers a
// ping, for at most cfg.ConnectWait. The caller closes the pool. Errors
// never contain the DSN.
func Open(ctx context.Context, cfg Config, logger *slog.Logger) (*pgxpool.Pool, error) {
	if logger == nil {
		logger = slog.New(slog.DiscardHandler)
	}
	pc, err := cfg.poolConfig()
	if err != nil {
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	pool, err := pgxpool.NewWithConfig(ctx, pc)
	if err != nil {
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	if err := waitForPing(ctx, pool, cfg.ConnectWait, logger); err != nil {
		pool.Close()
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	return pool, nil
}

// pinger is the part of *pgxpool.Pool that waitForPing uses.
type pinger interface {
	Ping(ctx context.Context) error
}

// waitForPing pings until the database answers or wait passes.
func waitForPing(ctx context.Context, p pinger, wait time.Duration, logger *slog.Logger) error {
	ctx, cancel := context.WithTimeout(ctx, wait)
	defer cancel()
	ticker := time.NewTicker(pingInterval)
	defer ticker.Stop()
	for attempt := 1; ; attempt++ {
		err := p.Ping(ctx)
		if err == nil {
			return nil
		}
		if attempt == 1 {
			logger.InfoContext(ctx, "waiting for postgres", "wait", wait.String())
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("no answer within %s after %d attempts: %w", wait, attempt, err)
		case <-ticker.C:
		}
	}
}

// migrations holds the goose migrations. sqlc reads the same files as its
// schema.
//
//go:embed migrations/*.sql
var migrations embed.FS

// Migrations returns the embedded migration files, at the root of the
// returned file system.
func Migrations() (fs.FS, error) {
	sub, err := fs.Sub(migrations, "migrations")
	if err != nil {
		return nil, fmt.Errorf("migrations: %w", err)
	}
	return sub, nil
}

// Migrate applies every migration that the database does not have yet. It
// is safe to run from several processes at the same time: a PostgreSQL
// advisory lock lets one of them work, and the others wait and then find
// nothing to do. It logs each applied migration.
func Migrate(ctx context.Context, pool *pgxpool.Pool, logger *slog.Logger) error {
	if logger == nil {
		logger = slog.New(slog.DiscardHandler)
	}
	files, err := Migrations()
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	db := stdlib.OpenDBFromPool(pool)
	defer db.Close()

	provider, err := goose.NewProvider(goose.DialectPostgres, db, files,
		goose.WithSessionLocker(locker),
		goose.WithDisableGlobalRegistry(true),
	)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	results, err := provider.Up(ctx)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	for _, r := range results {
		logger.InfoContext(ctx, "migration applied",
			"version", r.Source.Version, "file", r.Source.Path, "duration", r.Duration.String())
	}
	return nil
}
